COMMENT ON COLUMN marriages.partner_a IS 'The partner the stated fact names first.';
COMMENT ON COLUMN marriages.partner_b IS 'The partner the stated fact names second.';

-- ----------------------------------------------------------------------------
-- Friendships: One row per stated isFriendOf fact, read both ways by the symmetric rule, like a marriage.
-- ----------------------------------------------------------------------------
CREATE TABLE friendships (
  friendship_id                       TEXT                 PRIMARY KEY,         -- Key of the fact: subject|property|object, as her page names it.
  reasoning                           TEXT                ,                     -- The world this fact belongs to.
