$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION erb_text_number(d DATE, decimals INTEGER, grouped BOOLEAN, percent BOOLEAN)
RETURNS TEXT AS $$
  SELECT CASE WHEN d IS NULL THEN NULL ELSE erb_date_text(d) END;
$$ LANGUAGE sql IMMUTABLE;


