CREATE OR REPLACE FUNCTION calc_grandparenthoods_name(p_grandparenthood_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_grandparenthoods_links(p_grandparenthood_id) THEN (CONCAT(calc_grandparenthoods_grandparent_label(p_grandparenthood_id), ' is grandparent of ', calc_grandparenthoods_grandchild_label(p_grandparenthood_id)))::text ELSE (CONCAT('(', (SELECT NULLIF(upper_link, '') FROM grandparenthoods WHERE grandparenthood_id = p_grandparenthood_id), ' does not lead to ', (SELECT NULLIF(lower_link, '') FROM grandparenthoods WHERE grandparenthood_id = p_grandparenthood_id), ')'))::text END)::text;
