-- Field: Grandparenthoods.Links
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grandparenthoods_links(p_grandparenthood_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_grandparenthoods_upper_child(p_grandparenthood_id), '') = COALESCE(calc_grandparenthoods_lower_parent(p_grandparenthood_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

