-- ----------------------------------------------------------------------------
-- vw_reasoning: The one world the rules reason over, and the switch of each of her five rules. Every table links here, so each rule's switch is one lookup away from the field it gates, and every count of the world rolls up here.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_reasoning CASCADE;
CREATE VIEW vw_reasoning WITH (security_invoker = ON) AS
SELECT
  t.reasoning_id,                                                               -- Key of the world.
  calc_reasoning_name(t.reasoning_id) AS name,                                  -- Order 1. The world's name.
  t.label,                                                                      -- The world's name.
  t.inverse_is_on,                                                              -- Inverse rule: a parent link also gives a child link between the same two people (isChildOf, the inverse of isParentOf).
  t.symmetric_is_on,                                                            -- Symmetric rule: a spouse link or a friend link holds for both people.
  t.chain_is_on,                                                                -- Property chain: a parent of a parent is a grandparent (isParentOf then isParentOf gives isGrandparentOf).
  t.domain_range_is_on,                                                         -- Domain and range: whoever attends something, or has a grade level or a role, is a Person; whatever is attended is a School.
  t.disjoint_is_on,                                                             -- Disjoint: no one is both the parent and the spouse of the same person (isParentOf is disjoint with isSpouseOf).
  calc_reasoning_count_of_individuals(t.reasoning_id) AS count_of_individuals,  -- Order 1. Every individual of the world.
  calc_reasoning_count_of_people(t.reasoning_id) AS count_of_people,            -- Order 3. Individuals that are a Person, asserted or concluded.
  calc_reasoning_count_of_schools(t.reasoning_id) AS count_of_schools,          -- Order 3. Individuals that are a School, asserted or concluded.
  calc_reasoning_count_of_stated_parenthoods(t.reasoning_id) AS count_of_stated_parenthoods,-- Order 1. Stated isParentOf facts: one per Parenthoods row.
  calc_reasoning_count_of_stated_marriages(t.reasoning_id) AS count_of_stated_marriages,-- Order 1. Stated isSpouseOf facts: one per Marriages row.
  calc_reasoning_count_of_stated_friendships(t.reasoning_id) AS count_of_stated_friendships,-- Order 1. Stated isFriendOf facts: one per Friendships row.
  calc_reasoning_count_of_stated_individual_facts(t.reasoning_id) AS count_of_stated_individual_facts,-- Order 3. Stated facts held as columns of an individual: attends, has age and is a.
  calc_reasoning_count_of_current_grade_levels(t.reasoning_id) AS count_of_current_grade_levels,-- Order 3. Grade level facts in effect: each person's current grade.
  calc_reasoning_count_of_current_roles(t.reasoning_id) AS count_of_current_roles,-- Order 3. Role facts in effect: each person's current role.
  calc_reasoning_count_of_stated_facts(t.reasoning_id) AS count_of_stated_facts,-- Order 4. Every stated fact in effect, wherever it is held.
  calc_reasoning_count_of_child_of_conclusions(t.reasoning_id) AS count_of_child_of_conclusions,-- Order 2. isChildOf facts the inverse rule concludes: one per parenthood.
  calc_reasoning_count_of_mirrored_marriages(t.reasoning_id) AS count_of_mirrored_marriages,-- Order 2. isSpouseOf facts the symmetric rule concludes: one per marriage, read from its second partner.
  calc_reasoning_count_of_mirrored_friendships(t.reasoning_id) AS count_of_mirrored_friendships,-- Order 2. isFriendOf facts the symmetric rule concludes: one per friendship, read from its second friend.
  calc_reasoning_count_of_grandparent_conclusions(t.reasoning_id) AS count_of_grandparent_conclusions,-- Order 4. isGrandparentOf facts the property chain concludes.
  calc_reasoning_count_of_person_conclusions(t.reasoning_id) AS count_of_person_conclusions,-- Order 3. Individuals the domain rule makes a Person that no one asserted was one.
  calc_reasoning_count_of_school_conclusions(t.reasoning_id) AS count_of_school_conclusions,-- Order 3. Individuals the range rule makes a School that no one asserted was one.
  calc_reasoning_count_of_conclusions(t.reasoning_id) AS count_of_conclusions,  -- Order 5. Every fact the rules conclude that no one stated.
  calc_reasoning_count_of_contradictions(t.reasoning_id) AS count_of_contradictions,-- Order 4. Parenthoods the disjoint rule flags: the parent is also the child's spouse.
  calc_reasoning_is_consistent(t.reasoning_id) AS is_consistent,                -- Order 5. No contradiction the disjoint rule can see.
  calc_reasoning_summary(t.reasoning_id) AS summary                             -- Order 6. The world in one line.
FROM reasoning t;

-- ----------------------------------------------------------------------------
-- vw_portraits: The picture of each individual, linked from its Fandom page (never downloaded).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_portraits CASCADE;
CREATE VIEW vw_portraits WITH (security_invoker = ON) AS
SELECT
  t.portrait_id,                                                                -- Key of the portrait: the short name the page files it under.
  t.display_name,                                                               -- The name on the portrait's Fandom page.
  t.page,                                                                       -- The Fandom page credited for the portrait.
  t.image,                                                                      -- The original Fandom image.
  t.crop,                                                                       -- The crop as an SVG viewBox: x y width height.
  t.width,                                                                      -- The original image's width in pixels.
  t.height,                                                                     -- The original image's height in pixels.
  t.sort_order,                                                                 -- Position in the credits.
  calc_portraits_name(t.portrait_id) AS name                                    -- Order 1. The portrait's name.
FROM portraits t;

-- ----------------------------------------------------------------------------
-- vw_individuals: Every individual of the world (owl:Thing). What is said about one individual alone is a column of its row: its age, the place it attends, whether it is asserted to be a Person or a School. Its current grade level and role come from their records. Class membership is a formula, not a table, because it is concluded: no one stated that South Park Elementary is a School.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_individuals CASCADE;
CREATE VIEW vw_individuals WITH (security_invoker = ON) AS
SELECT
  t.individual_id,                                                              -- Key of the individual.
  calc_individuals_name(t.individual_id) AS name,                               -- Order 1. The individual's name.
  t.label,                                                                      -- The individual's name.
  t.sort_order,                                                                 -- Position in the cast.
  t.reasoning,                                                                  -- The world this individual belongs to.
  t.portrait,                                                                   -- The individual's picture.
  calc_individuals_portrait_image(t.individual_id) AS portrait_image,           -- Order 1. The picture's image.
  calc_individuals_symmetric_is_on(t.individual_id) AS symmetric_is_on,         -- Order 1. The Symmetric rule's switch, read from the reasoning this row belongs to.
  calc_individuals_domain_range_is_on(t.individual_id) AS domain_range_is_on,   -- Order 1. The DomainRange rule's switch, read from the reasoning this row belongs to.
  t.is_asserted_person,                                                         -- Stated: this individual is a Person (isA Person).
  t.is_asserted_school,                                                         -- Stated: this individual is a School (isA School).
  t.age,                                                                        -- Stated: hasAge.
  t.attends,                                                                    -- Stated: the place this individual attends (attends). Its range is School.
  calc_individuals_attends_label(t.individual_id) AS attends_label,             -- Order 1. The name of the place attended.
  calc_individuals_has_age(t.individual_id) AS has_age,                         -- Order 1. An age is stated.
  calc_individuals_has_attends(t.individual_id) AS has_attends,                 -- Order 1. A place attended is stated.
  calc_individuals_stated_fact_count(t.individual_id) AS stated_fact_count,     -- Order 2. Stated facts held on this row: is a Person, is a School, has age, attends.
  calc_individuals_count_of_grade_levels_on(t.individual_id) AS count_of_grade_levels_on,-- Order 1. Grade level records switched on for this individual.
  calc_individuals_latest_grade_level_seq(t.individual_id) AS latest_grade_level_seq,-- Order 1. When the latest grade level switched on was stated: the one in effect.
  calc_individuals_has_grade_level(t.individual_id) AS has_grade_level,         -- Order 2. A grade level is in effect.
  calc_individuals_current_grade_level_record(t.individual_id) AS current_grade_level_record,-- Order 3. Key of the grade level record in effect.
  calc_individuals_grade_level(t.individual_id) AS grade_level,                 -- Order 4. The grade level in effect: the latest one switched on (hasGradeLevel keeps one current value).
  calc_individuals_count_of_roles_on(t.individual_id) AS count_of_roles_on,     -- Order 1. Role records switched on for this individual.
  calc_individuals_latest_role_seq(t.individual_id) AS latest_role_seq,         -- Order 1. When the latest role switched on was stated: the one in effect.
  calc_individuals_has_role(t.individual_id) AS has_role,                       -- Order 2. A role is in effect.
  calc_individuals_current_role_record(t.individual_id) AS current_role_record, -- Order 3. Key of the role record in effect.
  calc_individuals_role(t.individual_id) AS role,                               -- Order 4. The role in effect: the latest one switched on (hasRole keeps one current value).
  calc_individuals_has_person_evidence(t.individual_id) AS has_person_evidence, -- Order 3. Something is stated that only a Person can have: a place attended, a grade level or a role (the domain of attends, hasGradeLevel and hasRole).
  calc_individuals_is_person_by_domain(t.individual_id) AS is_person_by_domain, -- Order 4. The domain rule makes this individual a Person.
  calc_individuals_is_person(t.individual_id) AS is_person,                     -- Order 5. A Person, asserted or concluded. Open world: true, or not known.
  calc_individuals_is_person_concluded(t.individual_id) AS is_person_concluded, -- Order 5. A Person only because the domain rule says so.
  calc_individuals_attended_by_count(t.individual_id) AS attended_by_count,     -- Order 1. Individuals that attend this one.
  calc_individuals_is_school_by_range(t.individual_id) AS is_school_by_range,   -- Order 2. The range rule makes this individual a School: someone attends it.
  calc_individuals_is_school(t.individual_id) AS is_school,                     -- Order 3. A School, asserted or concluded. Open world: true, or not known.
  calc_individuals_is_school_concluded(t.individual_id) AS is_school_concluded, -- Order 3. A School only because the range rule says so.
  calc_individuals_child_count(t.individual_id) AS child_count,                 -- Order 1. Children: parenthoods where this individual is the parent (isParentOf).
  calc_individuals_parent_count(t.individual_id) AS parent_count,               -- Order 1. Parents: the same parenthoods read from the child's end. The link is there whatever the inverse rule says.
  calc_individuals_child_of_fact_count(t.individual_id) AS child_of_fact_count, -- Order 2. isChildOf facts about this individual: its parenthoods read from its end, when the inverse rule is on.
  calc_individuals_grandchild_count(t.individual_id) AS grandchild_count,       -- Order 5. Grandchildren the property chain concludes (isGrandparentOf).
  calc_individuals_grandparent_count(t.individual_id) AS grandparent_count,     -- Order 5. Grandparents the property chain concludes, read from the grandchild's end.
  calc_individuals_descendant_count(t.individual_id) AS descendant_count,       -- Order 1. Everyone below this individual through one or more parenthoods: the transitive closure, which her page does not draw.
  calc_individuals_ancestor_count(t.individual_id) AS ancestor_count,           -- Order 1. Everyone above this individual through one or more parenthoods.
  calc_individuals_stated_spouse_count(t.individual_id) AS stated_spouse_count, -- Order 2. Marriages that name this individual first: the stated isSpouseOf.
  calc_individuals_mirrored_spouse_count(t.individual_id) AS mirrored_spouse_count,-- Order 3. Marriages that name this individual second, when the symmetric rule reads them both ways.
  calc_individuals_spouse_count(t.individual_id) AS spouse_count,               -- Order 4. Spouses: isSpouseOf facts about this individual, stated or mirrored.
  calc_individuals_stated_friend_count(t.individual_id) AS stated_friend_count, -- Order 2. Friendships that name this individual first: the stated isFriendOf.
  calc_individuals_mirrored_friend_count(t.individual_id) AS mirrored_friend_count,-- Order 3. Friendships that name this individual second, when the symmetric rule reads them both ways.
  calc_individuals_friend_count(t.individual_id) AS friend_count                -- Order 4. Friends: isFriendOf facts about this individual, stated or mirrored.
FROM individuals t;

-- ----------------------------------------------------------------------------
-- vw_parenthoods: One row per stated isParentOf fact. A person has many children and a child more than one parent, so the link is its own entity with two links to Individuals. The inverse rule's isChildOf is not stored: it is this row read from the child's end.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_parenthoods CASCADE;
CREATE VIEW vw_parenthoods WITH (security_invoker = ON) AS
SELECT
  t.parenthood_id,                                                              -- Key of the fact: subject|property|object, as her page names it.
  calc_parenthoods_name(t.parenthood_id) AS name,                               -- Order 2. The stated fact in words.
  t.reasoning,                                                                  -- The world this fact belongs to.
  t.parent,                                                                     -- The parent (the subject of isParentOf).
  t.child,                                                                      -- The child (the object of isParentOf).
  calc_parenthoods_parent_label(t.parenthood_id) AS parent_label,               -- Order 1. The parent's name.
  calc_parenthoods_child_label(t.parenthood_id) AS child_label,                 -- Order 1. The child's name.
  calc_parenthoods_inverse_is_on(t.parenthood_id) AS inverse_is_on,             -- Order 1. The Inverse rule's switch, read from the reasoning this row belongs to.
  calc_parenthoods_symmetric_is_on(t.parenthood_id) AS symmetric_is_on,         -- Order 1. The Symmetric rule's switch, read from the reasoning this row belongs to.
  calc_parenthoods_disjoint_is_on(t.parenthood_id) AS disjoint_is_on,           -- Order 1. The Disjoint rule's switch, read from the reasoning this row belongs to.
  calc_parenthoods_child_of_holds(t.parenthood_id) AS child_of_holds,           -- Order 2. The inverse rule concludes the child is child of the parent. Open world: true, or not known.
  calc_parenthoods_child_of_sentence(t.parenthood_id) AS child_of_sentence,     -- Order 2. The inverse fact in words.
  calc_parenthoods_spouse_as_stated_count(t.parenthood_id) AS spouse_as_stated_count,-- Order 3. Marriages stated with the parent first and the child second.
  calc_parenthoods_spouse_as_mirrored_count(t.parenthood_id) AS spouse_as_mirrored_count,-- Order 3. Marriages stated with the child first, which make the parent the child's spouse when the symmetric rule mirrors them.
  calc_parenthoods_is_contradiction(t.parenthood_id) AS is_contradiction        -- Order 4. The disjoint rule: the parent is also the child's spouse. Open world: true, or not known.
FROM parenthoods t;

-- ----------------------------------------------------------------------------
-- vw_marriages: One row per stated isSpouseOf fact. A marriage has no direction: the symmetric rule is the same row counted from its second partner's end.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_marriages CASCADE;
CREATE VIEW vw_marriages WITH (security_invoker = ON) AS
SELECT
  t.marriage_id,                                                                -- Key of the fact: subject|property|object, as her page names it.
  calc_marriages_name(t.marriage_id) AS name,                                   -- Order 2. The stated fact in words.
  t.reasoning,                                                                  -- The world this fact belongs to.
  t.partner_a,                                                                  -- The partner the stated fact names first.
  t.partner_b,                                                                  -- The partner the stated fact names second.
  calc_marriages_partner_a_label(t.marriage_id) AS partner_a_label,             -- Order 1. The partnera's name.
  calc_marriages_partner_b_label(t.marriage_id) AS partner_b_label,             -- Order 1. The partnerb's name.
  calc_marriages_symmetric_is_on(t.marriage_id) AS symmetric_is_on,             -- Order 1. The Symmetric rule's switch, read from the reasoning this row belongs to.
  calc_marriages_mirror_holds(t.marriage_id) AS mirror_holds,                   -- Order 2. The symmetric rule concludes the second partner is spouse of the first. Open world: true, or not known.
  calc_marriages_mirror_sentence(t.marriage_id) AS mirror_sentence              -- Order 2. The mirrored fact in words.
FROM marriages t;

-- ----------------------------------------------------------------------------
-- vw_friendships: One row per stated isFriendOf fact, read both ways by the symmetric rule, like a marriage.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_friendships CASCADE;
CREATE VIEW vw_friendships WITH (security_invoker = ON) AS
SELECT
  t.friendship_id,                                                              -- Key of the fact: subject|property|object, as her page names it.
  calc_friendships_name(t.friendship_id) AS name,                               -- Order 2. The stated fact in words.
  t.reasoning,                                                                  -- The world this fact belongs to.
  t.friend_a,                                                                   -- The friend the stated fact names first.
  t.friend_b,                                                                   -- The friend the stated fact names second.
  calc_friendships_friend_a_label(t.friendship_id) AS friend_a_label,           -- Order 1. The frienda's name.
  calc_friendships_friend_b_label(t.friendship_id) AS friend_b_label,           -- Order 1. The friendb's name.
  calc_friendships_symmetric_is_on(t.friendship_id) AS symmetric_is_on,         -- Order 1. The Symmetric rule's switch, read from the reasoning this row belongs to.
  calc_friendships_mirror_holds(t.friendship_id) AS mirror_holds,               -- Order 2. The symmetric rule concludes the second friend is friend of the first. Open world: true, or not known.
  calc_friendships_mirror_sentence(t.friendship_id) AS mirror_sentence          -- Order 2. The mirrored fact in words.
FROM friendships t;

-- ----------------------------------------------------------------------------
-- vw_grandparenthoods: The property chain isParentOf then isParentOf, as rows: every ordered pair of parenthoods is a candidate, and it holds when the first one's child is the second one's parent. A formula cannot add a row, so the candidates are data (every pair, decided by nothing about the family) and whether one holds is a formula.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_grandparenthoods CASCADE;
CREATE VIEW vw_grandparenthoods WITH (security_invoker = ON) AS
SELECT
  t.grandparenthood_id,                                                         -- Key: the upper parenthood, then the lower one.
  calc_grandparenthoods_name(t.grandparenthood_id) AS name,                     -- Order 4. The concluded fact in words, or why this pair concludes nothing.
  t.reasoning,                                                                  -- The world this candidate belongs to.
  t.upper_link,                                                                 -- The first link: grandparent to the middle generation.
  t.lower_link,                                                                 -- The second link: the middle generation to the grandchild.
  calc_grandparenthoods_grandparent(t.grandparenthood_id) AS grandparent,       -- Order 1. The upper link's parent.
  calc_grandparenthoods_upper_child(t.grandparenthood_id) AS upper_child,       -- Order 1. The upper link's child.
  calc_grandparenthoods_lower_parent(t.grandparenthood_id) AS lower_parent,     -- Order 1. The lower link's parent.
  calc_grandparenthoods_grandchild(t.grandparenthood_id) AS grandchild,         -- Order 1. The lower link's child.
  calc_grandparenthoods_grandparent_label(t.grandparenthood_id) AS grandparent_label,-- Order 2. The grandparent's name.
  calc_grandparenthoods_grandchild_label(t.grandparenthood_id) AS grandchild_label,-- Order 2. The grandchild's name.
  calc_grandparenthoods_links(t.grandparenthood_id) AS links,                   -- Order 2. The upper link's child is the lower link's parent: the two links make a chain.
  calc_grandparenthoods_chain_is_on(t.grandparenthood_id) AS chain_is_on,       -- Order 1. The Chain rule's switch, read from the reasoning this row belongs to.
  calc_grandparenthoods_holds(t.grandparenthood_id) AS holds                    -- Order 3. The property chain concludes isGrandparentOf. Open world: true, or not known.
FROM grandparenthoods t;

-- ----------------------------------------------------------------------------
-- vw_grade_level_records: Every grade level stated for an individual, kept when a later one replaces it: her page keeps one current grade, the latest switched on. The current value is time (which was stated last), not a flag.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_grade_level_records CASCADE;
CREATE VIEW vw_grade_level_records WITH (security_invoker = ON) AS
SELECT
  t.grade_level_record_id,                                                      -- Key: individual|grade|when it was stated.
  calc_grade_level_records_name(t.grade_level_record_id) AS name,               -- Order 2. The fact in words.
  t.reasoning,                                                                  -- The world this record belongs to.
  t.individual,                                                                 -- Whose value it is.
  calc_grade_level_records_individual_label(t.grade_level_record_id) AS individual_label,-- Order 1. Whose value it is, by name.
  t.grade_level,                                                                -- The value stated.
  t.stated_seq,                                                                 -- When the value was switched on, in the order facts are stated (transaction time). The latest one switched on is in effect.
  t.is_on,                                                                      -- The value is switched on. A value switched off stays in the record.
  calc_grade_level_records_individual_latest_seq(t.grade_level_record_id) AS individual_latest_seq,-- Order 2. When the individual's latest value switched on was stated.
  calc_grade_level_records_is_current(t.grade_level_record_id) AS is_current,   -- Order 3. This value is the one in effect: switched on, and the latest switched on.
  calc_grade_level_records_key_is_canonical(t.grade_level_record_id) AS key_is_canonical-- Order 1. The key is individual|grade|StatedSeq, the key the individual's current value is looked up by.
FROM grade_level_records t;

-- ----------------------------------------------------------------------------
-- vw_role_records: Every role stated for an individual; the latest one switched on is in effect, like a grade level.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_role_records CASCADE;
CREATE VIEW vw_role_records WITH (security_invoker = ON) AS
SELECT
  t.role_record_id,                                                             -- Key: individual|role|when it was stated.
  calc_role_records_name(t.role_record_id) AS name,                             -- Order 2. The fact in words.
  t.reasoning,                                                                  -- The world this record belongs to.
  t.individual,                                                                 -- Whose value it is.
  calc_role_records_individual_label(t.role_record_id) AS individual_label,     -- Order 1. Whose value it is, by name.
  t.role,                                                                       -- The value stated.
  t.stated_seq,                                                                 -- When the value was switched on, in the order facts are stated (transaction time). The latest one switched on is in effect.
  t.is_on,                                                                      -- The value is switched on. A value switched off stays in the record.
  calc_role_records_individual_latest_seq(t.role_record_id) AS individual_latest_seq,-- Order 2. When the individual's latest value switched on was stated.
  calc_role_records_is_current(t.role_record_id) AS is_current,                 -- Order 3. This value is the one in effect: switched on, and the latest switched on.
  calc_role_records_key_is_canonical(t.role_record_id) AS key_is_canonical      -- Order 1. The key is individual|role|StatedSeq, the key the individual's current value is looked up by.
FROM role_records t;

-- ----------------------------------------------------------------------------
-- vw_parenthoods_closure: Transitive closure of isParentOf (an owl:TransitiveProperty reading of it, which her page does not draw): every (ancestor, descendant) pair through one or more parenthoods, materialized as vw_parenthoods_closure.
-- Cycle-safe transitive closure of parenthoods(parent -> child) [junction edge table].
-- Columns: from_id, to_id, hop_distance (shortest derivation), is_inferred
--          (TRUE iff no direct hop-1 edge asserts the pair).
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_parenthoods_closure CASCADE;
CREATE VIEW vw_parenthoods_closure WITH (security_invoker = ON) AS
WITH RECURSIVE edges AS (
    SELECT parent AS from_id, child AS to_id
    FROM parenthoods
    -- Treat NULL and empty-string FKs as 'no edge' (the transpiler stores absent
    -- relationship values as '' rather than NULL, so both must be excluded).
    WHERE parent IS NOT NULL AND parent <> '' AND child IS NOT NULL AND child <> ''
),
closure AS (
    -- Base: the directly-asserted edges (hop 1).
    SELECT
        e.from_id,
        e.to_id,
        1 AS hop_distance,
        ARRAY[e.from_id, e.to_id] AS path
    FROM edges e
    UNION ALL
    -- Step: extend each path by one asserted edge. Interior nodes are never
    -- revisited, so cyclic edge sets terminate (cycle-safe). Returning to the
    -- path's own origin IS allowed, exactly once: it emits (x, x) for every x
    -- that lies on a cycle, which is what transitive closure means. A path that
    -- has closed back on its origin is complete and is not extended further.
    SELECT
        cl.from_id,
        e.to_id,
        cl.hop_distance + 1,
        cl.path || e.to_id
    FROM closure cl
    JOIN edges e ON e.from_id = cl.to_id
    WHERE cl.to_id <> cl.from_id
      AND NOT (e.to_id = ANY(cl.path[2:]))
)
SELECT
    cl.from_id,
    cl.to_id,
    MIN(cl.hop_distance) AS hop_distance,
    NOT EXISTS (
        SELECT 1 FROM edges e2
        WHERE e2.from_id = cl.from_id AND e2.to_id = cl.to_id
    ) AS is_inferred
FROM closure cl
GROUP BY cl.from_id, cl.to_id;




